package android.net;import java.util.*;public final class Uri {private final String text;private Uri(String s){text=s;}public static Uri parse(String s){return new Uri(s);}public String toString(){return text;}public String getLastPathSegment(){String s=text.split("[?]",2)[0];return s.substring(s.lastIndexOf('/')+1);}public Builder buildUpon(){return new Builder(text);}public static class Builder{String path;String query="";public Builder(String s){String[]p=s.split("[?]",2);path=p[0];if(p.length>1)query=p[1];}public Builder appendPath(String s){path+="/"+s;return this;}public Builder appendQueryParameter(String k,String v){query+=(query.isEmpty()?"":"&")+k+"="+v;return this;}public Uri build(){return Uri.parse(path+(query.isEmpty()?"":"?"+query));}}}
